// Package s3 implements storage.ObjectStorage using the AWS S3 protocol.
//
// All three supported providers (AWS S3, Cloudflare R2, MinIO) speak the same
// S3 protocol — only the endpoint and path-style configuration differ.
package s3

import (
	"context"
	"fmt"
	"io"
	"mime"
	"net/url"
	"path"
	"strings"
	"time"

	"github.com/aws/aws-sdk-go-v2/aws"
	"github.com/aws/aws-sdk-go-v2/config"
	"github.com/aws/aws-sdk-go-v2/credentials"
	"github.com/aws/aws-sdk-go-v2/service/s3"
	"github.com/aws/aws-sdk-go-v2/service/s3/types"
)

// Config carries the provider-specific settings.
//
// AWS S3:         Endpoint="", Region="us-east-1",   ForcePathStyle=false
// Cloudflare R2:  Endpoint="https://<account>.r2.cloudflarestorage.com", Region="auto"
// MinIO:          Endpoint="http://localhost:9000",   ForcePathStyle=true
type Config struct {
	Endpoint       string
	AccessKey      string
	SecretKey      string
	Bucket         string
	Region         string
	ForcePathStyle bool
	// PublicURL is the base URL used to construct public download links.
	PublicURL string
	// PublicEndpoint is the storage address as the browser sees it, used only to
	// sign download links. Set it when the API reaches storage on a private
	// address (e.g. http://minio:9000 inside docker compose) that a browser
	// can't open. Defaults to Endpoint.
	PublicEndpoint string
	// PrivateBucket is the bucket for private documents (no public-read policy).
	// Access is exclusively via presigned URLs generated by the API.
	// Defaults to Bucket+"-docs" when empty.
	PrivateBucket string
}

// Client wraps the AWS SDK v2 S3 client.
type Client struct {
	s3     *s3.Client
	signer *s3.PresignClient
	bucket string
	pubURL string
}

// New creates a *Client for the given configuration.
// *Client satisfies storage.ObjectStorage via structural typing — no explicit import needed.
func New(ctx context.Context, cfg Config) (*Client, error) {
	creds := credentials.NewStaticCredentialsProvider(cfg.AccessKey, cfg.SecretKey, "")

	opts := []func(*config.LoadOptions) error{
		config.WithRegion(cfg.Region),
		config.WithCredentialsProvider(creds),
	}

	awsCfg, err := config.LoadDefaultConfig(ctx, opts...)
	if err != nil {
		return nil, fmt.Errorf("s3: failed to load config: %w", err)
	}

	clientOpts := []func(*s3.Options){
		func(o *s3.Options) {
			o.UsePathStyle = cfg.ForcePathStyle
		},
	}
	if cfg.Endpoint != "" {
		clientOpts = append(clientOpts, func(o *s3.Options) {
			o.BaseEndpoint = aws.String(cfg.Endpoint)
		})
	}

	client := s3.NewFromConfig(awsCfg, clientOpts...)

	// Presigned links carry the host they were signed for, so they must be
	// signed with the address the browser will use. Signing needs no network
	// call, so this client never talks to the public address itself.
	signer := s3.NewPresignClient(client)
	if cfg.PublicEndpoint != "" {
		public := cfg.PublicEndpoint
		signer = s3.NewPresignClient(client, func(o *s3.PresignOptions) {
			o.ClientOptions = append(o.ClientOptions, func(so *s3.Options) {
				so.BaseEndpoint = aws.String(public)
			})
		})
	}

	c := &Client{
		s3:     client,
		signer: signer,
		bucket: cfg.Bucket,
		pubURL: strings.TrimRight(cfg.PublicURL, "/"),
	}

	// Ensure the public bucket exists (images, logos, covers).
	if err := c.ensureBucket(ctx, cfg.Bucket); err != nil {
		return nil, fmt.Errorf("s3: failed to ensure public bucket %q: %w", cfg.Bucket, err)
	}

	// Ensure the private bucket exists (documents, attachments — no public-read policy).
	if cfg.PrivateBucket != "" && cfg.PrivateBucket != cfg.Bucket {
		if err := c.ensurePrivateBucket(ctx, cfg.PrivateBucket); err != nil {
			return nil, fmt.Errorf("s3: failed to ensure private bucket %q: %w", cfg.PrivateBucket, err)
		}
	}

	return c, nil
}

// ensurePrivateBucket creates the bucket if it does not exist.
// No public-read policy is applied — objects are only accessible via presigned URLs.
func (c *Client) ensurePrivateBucket(ctx context.Context, bucket string) error {
	_, err := c.s3.HeadBucket(ctx, &s3.HeadBucketInput{Bucket: aws.String(bucket)})
	if err == nil {
		return nil // already exists
	}
	_, err = c.s3.CreateBucket(ctx, &s3.CreateBucketInput{Bucket: aws.String(bucket)})
	if err != nil {
		return fmt.Errorf("create private bucket: %w", err)
	}
	return nil
}

// ensureBucket creates the bucket if it does not already exist,
// then applies a public-read policy so uploaded files are accessible via URL.
func (c *Client) ensureBucket(ctx context.Context, bucket string) error {
	// Check if bucket exists — HeadBucket returns 200 if it does.
	_, err := c.s3.HeadBucket(ctx, &s3.HeadBucketInput{
		Bucket: aws.String(bucket),
	})
	if err == nil {
		// Bucket already exists — nothing to do.
		return nil
	}

	// Create the bucket.
	_, err = c.s3.CreateBucket(ctx, &s3.CreateBucketInput{
		Bucket: aws.String(bucket),
	})
	if err != nil {
		return fmt.Errorf("create bucket: %w", err)
	}

	// Apply a public-read bucket policy so uploaded files are accessible without auth.
	policy := fmt.Sprintf(`{
		"Version": "2012-10-17",
		"Statement": [{
			"Sid": "PublicRead",
			"Effect": "Allow",
			"Principal": "*",
			"Action": ["s3:GetObject"],
			"Resource": ["arn:aws:s3:::%s/*"]
		}]
	}`, bucket)

	_, err = c.s3.PutBucketPolicy(ctx, &s3.PutBucketPolicyInput{
		Bucket: aws.String(bucket),
		Policy: aws.String(policy),
	})
	if err != nil {
		// Non-fatal — bucket was created, policy might not be supported (e.g. AWS requires different config).
		fmt.Printf("s3: warning: could not set public-read policy on %q: %v\n", bucket, err)
	}

	return nil
}

// Upload stores data at the given key and returns the public URL.
//
// No per-object ACL is set. Whether an object can be read without credentials
// is a property of its bucket — the public one carries a public-read policy
// from ensureBucket, or the provider's own public-access setting — and the
// private bucket is reached only through presigned URLs.
//
// Setting one here was wrong in three ways: it marked private documents
// public-read, R2 does not implement ACLs at all, and S3 buckets created since
// April 2023 default to bucket-owner-enforced, where any ACL makes PutObject
// fail with AccessControlListNotSupported.
func (c *Client) Upload(ctx context.Context, bucket, key string, data io.Reader, size int64, contentType string) (string, error) {
	if bucket == "" {
		bucket = c.bucket
	}
	if contentType == "" {
		contentType = "application/octet-stream"
	}

	_, err := c.s3.PutObject(ctx, &s3.PutObjectInput{
		Bucket:        aws.String(bucket),
		Key:           aws.String(key),
		Body:          data,
		ContentLength: aws.Int64(size),
		ContentType:   aws.String(contentType),
	})
	if err != nil {
		return "", fmt.Errorf("s3: upload %s: %w", key, err)
	}

	return c.publicURL(bucket, key), nil
}

// Download retrieves an object by key.
func (c *Client) Download(ctx context.Context, bucket, key string) (io.ReadCloser, error) {
	if bucket == "" {
		bucket = c.bucket
	}

	out, err := c.s3.GetObject(ctx, &s3.GetObjectInput{
		Bucket: aws.String(bucket),
		Key:    aws.String(key),
	})
	if err != nil {
		return nil, fmt.Errorf("s3: download %s: %w", key, err)
	}
	return out.Body, nil
}

// Delete removes an object by key.
func (c *Client) Delete(ctx context.Context, bucket, key string) error {
	if bucket == "" {
		bucket = c.bucket
	}

	_, err := c.s3.DeleteObject(ctx, &s3.DeleteObjectInput{
		Bucket: aws.String(bucket),
		Key:    aws.String(key),
	})
	if err != nil {
		return fmt.Errorf("s3: delete %s: %w", key, err)
	}
	return nil
}

// PresignedURL returns a time-limited URL for direct client download.
func (c *Client) PresignedURL(ctx context.Context, bucket, key string, expiry time.Duration) (string, error) {
	if bucket == "" {
		bucket = c.bucket
	}

	req, err := c.signer.PresignGetObject(ctx, &s3.GetObjectInput{
		Bucket: aws.String(bucket),
		Key:    aws.String(key),
	}, s3.WithPresignExpires(expiry))
	if err != nil {
		return "", fmt.Errorf("s3: presign %s: %w", key, err)
	}
	return req.URL, nil
}

// publicURL constructs the public download URL for a key.
func (c *Client) publicURL(bucket, key string) string {
	if c.pubURL != "" {
		return c.pubURL + "/" + key
	}
	// Default AWS S3 path-style fallback.
	return fmt.Sprintf("https://%s.s3.amazonaws.com/%s", bucket, key)
}

// FixContentTypes sets the content type, guessed from the file extension, on
// every object in the bucket that was stored as application/octet-stream or
// with no type at all. Uploads before content types were passed through were
// all stored that way, so browsers downloaded images instead of showing them.
// It returns how many objects it changed.
func (c *Client) FixContentTypes(ctx context.Context, bucket string) (int, error) {
	fixed := 0
	pages := s3.NewListObjectsV2Paginator(c.s3, &s3.ListObjectsV2Input{Bucket: aws.String(bucket)})
	for pages.HasMorePages() {
		page, err := pages.NextPage(ctx)
		if err != nil {
			return fixed, fmt.Errorf("s3: list %s: %w", bucket, err)
		}
		for _, obj := range page.Contents {
			key := aws.ToString(obj.Key)
			want := mime.TypeByExtension(strings.ToLower(path.Ext(key)))
			if want == "" {
				continue
			}
			head, err := c.s3.HeadObject(ctx, &s3.HeadObjectInput{Bucket: aws.String(bucket), Key: aws.String(key)})
			if err != nil {
				return fixed, fmt.Errorf("s3: head %s: %w", key, err)
			}
			if have := aws.ToString(head.ContentType); have != "" && have != "application/octet-stream" {
				continue
			}
			_, err = c.s3.CopyObject(ctx, &s3.CopyObjectInput{
				Bucket:            aws.String(bucket),
				Key:               aws.String(key),
				CopySource:        aws.String(bucket + "/" + url.PathEscape(key)),
				ContentType:       aws.String(want),
				Metadata:          head.Metadata,
				MetadataDirective: types.MetadataDirectiveReplace,
			})
			if err != nil {
				return fixed, fmt.Errorf("s3: copy %s: %w", key, err)
			}
			fixed++
		}
	}
	return fixed, nil
}
